From 2e966b4c34c0210ae7d12aae0021ec7f002751f3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:19:50 +0100
Subject: [PATCH] tooltips: use the solid background when the panel is opaque

Tooltips ignored the containment's opaque background preference and
always used the translucent SVG. Set their hints from the containment,
and make PlasmaWindow keep its own SVG instead of dialogs/background.

BUG: 512154
---
 src/declarativeimports/core/tooltiparea.cpp | 31 ++++++++++++++-------
 src/plasmaquick/plasmawindow.cpp            |  4 ++-
 2 files changed, 24 insertions(+), 11 deletions(-)

diff --git a/src/declarativeimports/core/tooltiparea.cpp b/src/declarativeimports/core/tooltiparea.cpp
index 41e346e4c..2f609f494 100644
--- a/src/declarativeimports/core/tooltiparea.cpp
+++ b/src/declarativeimports/core/tooltiparea.cpp
@@ -18,6 +18,7 @@
 #include <KSharedConfig>
 #include <KWindowEffects>
 #include <Plasma/Applet>
+#include <Plasma/Containment>

 using namespace Qt::Literals;

@@ -125,18 +126,28 @@ void ToolTipArea::showToolTip()
     // Unset the dialog's old contents before reparenting the dialog.
     dlg->setMainItem(nullptr);

-    Plasma::Types::Location location = m_location;
-    if (m_location == Plasma::Types::Floating) {
-        QQuickItem *p = parentItem();
-        while (p) {
-            PlasmaQuick::AppletQuickItem *appletItem = qobject_cast<PlasmaQuick::AppletQuickItem *>(p);
-            if (appletItem) {
-                location = appletItem->applet()->location();
-                break;
-            }
-            p = p->parentItem();
+    Plasma::Applet *applet = nullptr;
+    QQuickItem *p = parentItem();
+    while (p) {
+        PlasmaQuick::AppletQuickItem *appletItem = qobject_cast<PlasmaQuick::AppletQuickItem *>(p);
+        if (appletItem) {
+            applet = appletItem->applet();
+            break;
         }
+        p = p->parentItem();
+    }
+
+    Plasma::Types::Location location = m_location;
+    if (m_location == Plasma::Types::Floating && applet) {
+        location = applet->location();
+    }
+
+    Plasma::Containment *containment = applet ? applet->containment() : nullptr;
+    if (containment && containment->containmentType() == Plasma::Containment::CustomEmbedded) {
+        containment = containment->containment();
     }
+    const bool opaque = containment && (containment->containmentDisplayHints() & Plasma::Types::ContainmentPrefersOpaqueBackground);
+    dlg->setBackgroundHints(opaque ? PlasmaQuick::PlasmaWindow::SolidBackground : PlasmaQuick::PlasmaWindow::StandardBackground);

     if (mainItem()) {
         mainItem()->setProperty("toolTip", QVariant::fromValue(this));
diff --git a/src/plasmaquick/plasmawindow.cpp b/src/plasmaquick/plasmawindow.cpp
index 72ecb1c76..caddfaa2b 100644
--- a/src/plasmaquick/plasmawindow.cpp
+++ b/src/plasmaquick/plasmawindow.cpp
@@ -35,6 +35,7 @@ public:
     QPointer<QQuickItem> mainItem;
     DialogBackground *dialogBackground;
     PlasmaWindow::BackgroundHints backgroundHints = PlasmaWindow::StandardBackground;
+    QString svgPrefix;
 };

 PlasmaWindow::PlasmaWindow(const QString &svgPrefix)
@@ -44,6 +45,7 @@ PlasmaWindow::PlasmaWindow(const QString &svgPrefix)
     setColor(QColor(Qt::transparent));
     setFlags(Qt::FramelessWindowHint | Qt::WindowStaysOnTopHint);

+    d->svgPrefix = svgPrefix;
     d->shadows = DialogShadows::instance(svgPrefix);
     d->dialogBackground = new DialogBackground(contentItem());
     d->dialogBackground->setImagePath(svgPrefix);
@@ -203,7 +205,7 @@ void PlasmaWindow::setBackgroundHints(BackgroundHints hints)
     if (d->backgroundHints == PlasmaWindow::SolidBackground) {
         prefix = QStringLiteral("solid/");
     }
-    d->dialogBackground->setImagePath(prefix + QStringLiteral("dialogs/background"));
+    d->dialogBackground->setImagePath(prefix + d->svgPrefix);

     Q_EMIT backgroundHintsChanged();
 }
